import {
  ID8
} from "./repository-cache-hnvjv21h.js";

// src/plugin/provider/openrouter.ts
import { Effect } from "effect";
import { define } from "@opencode/plugin/effect/plugin";
var OpenRouterPlugin2 = define({
  id: "opencode.provider.openrouter",
  effect: Effect.fn(function* (ctx) {
    yield* ctx.provider.transform((evt) => {
      for (const item of evt.list()) {
        if (item.provider.package !== "@opencode/ai/providers/openrouter")
          continue;
        evt.update(item.provider.id, (provider) => {
          provider.headers = { ...provider.headers, "HTTP-Referer": "https://opencode.ai/", "X-Title": "opencode" };
        });
      }
    });
    yield* ctx.model.transform((models) => {
      for (const item of models.provider.list()) {
        if (item.provider.package !== "@opencode/ai/providers/openrouter")
          continue;
        for (const modelID of [ID8.make("gpt-5-chat-latest"), ID8.make("openai/gpt-5-chat")]) {
          if (!models.get(item.provider.id, modelID))
            continue;
          models.update(item.provider.id, modelID, (model) => {
            model.enabled = false;
          });
        }
      }
    });
  })
});

export { OpenRouterPlugin2 };
